using Eto.Forms; using Rhino; using Rhino.DocObjects;
namespace RhinoContextAssist;
internal sealed class ContextAssistController:IDisposable{readonly UITimer timer;readonly ContextAssistSettings settings;ContextToolbarForm? form;DateTime due=DateTime.MaxValue;bool started;public bool Enabled{get=>settings.Enabled;set{settings.Enabled=value;settings.Save();}}
 public ContextAssistController(ContextAssistSettings s){settings=s;timer=new UITimer{Interval=.10};timer.Elapsed+=(_,_)=>Tick();}
 public void Start(){if(started)return;started=true;RhinoDoc.SelectObjects+=Changed;RhinoDoc.DeselectObjects+=Changed;RhinoDoc.DeselectAllObjects+=Cleared;RhinoDoc.CloseDocument+=Closed;RhinoDoc.ActiveDocumentChanged+=Closed;RhinoApp.EscapeKeyPressed+=Escape;timer.Start();}
 void Changed(object?s,RhinoObjectSelectionEventArgs e){CloseToolbar();if(Enabled)due=DateTime.UtcNow.AddMilliseconds(160);}void Cleared(object?s,RhinoDeselectAllObjectsEventArgs e)=>Hide();void Closed(object?s,DocumentEventArgs e)=>Hide();void Escape(object?s,EventArgs e)=>Hide();
 void Tick(){var d=RhinoDoc.ActiveDoc;if(!Enabled||d is null||d.IsCommandRunning){Hide();return;}if(due==DateTime.MaxValue||DateTime.UtcNow<due)return;due=DateTime.MaxValue;RefreshNow();}
 public void RefreshNow(){var d=RhinoDoc.ActiveDoc;if(!Enabled||d is null||d.IsCommandRunning){Hide();return;}var c=SelectionAnalyzer.Analyze(d);var a=settings.Resolve(c.Kind);if(c.Kind==SelectionKind.None||a.Count==0){Hide();return;}CloseToolbar();var f=new ContextToolbarForm(Execute,Hide);f.Closed+=(_,_)=>{if(ReferenceEquals(form,f))form=null;};f.UpdateActions(c,a,settings);form=f;f.ShowAt(c,settings.PositionMode);}
 void Execute(ContextAction a){Hide();RhinoApp.InvokeOnUiThread((Action)(()=>RhinoApp.RunScript(a.Macro,false)));}public void Hide(){due=DateTime.MaxValue;CloseToolbar();}void CloseToolbar(){var f=form;form=null;if(f==null)return;try{f.Close();f.Dispose();}catch{}}
 public void Dispose(){timer.Stop();if(started){RhinoDoc.SelectObjects-=Changed;RhinoDoc.DeselectObjects-=Changed;RhinoDoc.DeselectAllObjects-=Cleared;RhinoDoc.CloseDocument-=Closed;RhinoDoc.ActiveDocumentChanged-=Closed;RhinoApp.EscapeKeyPressed-=Escape;}CloseToolbar();}}
